#!/usr/bin/env python3
"""Verify the docs.openaev.io links of the application code and of the docs pages against the built docs site.

Each https://docs.openaev.io/latest/<path>[#anchor] link found in the API, model and
front sources must match a page of the MkDocs build output (<site>/<path>/index.html),
and its anchor must be an id on that page. The same goes for every link of a page's content
in the built site that stays on the docs site: relative links, and absolute ones to
docs.openaev.io. Redirect pages generated by mkdocs-redirects are followed to their target.
Build the site first: `mkdocs build` in docs/.

Usage: check-docs-links.py [site-dir]   (default: docs/site)
"""

import re
import subprocess
import sys
from functools import cache
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import unquote, urljoin, urlsplit

REPO = Path(__file__).resolve().parents[2]
DOCS_ROOT = REPO / "docs" / "docs"
SOURCE_DIRS = ["openaev-api/src", "openaev-model/src", "openaev-front/src"]
SOURCE_SUFFIXES = {".properties", ".java", ".ts", ".tsx", ".js", ".jsx"}

# The front builds some links from a documentation root constant: `${DOCUMENTATION_ROOT_URL}/latest/...`.
ROOT = "https://docs.openaev.io"
# The site is served under a version: a page of the build output is at /latest/<path>.
VERSION_ROOT = f"{ROOT}/latest/"
URL_RE = re.compile(r"(?:https?://docs\.openaev\.io|\$\{documentation_?root_?url\})[^\s\"'`<>)\\]*", re.I)
ROOT_CONSTANT_RE = re.compile(r"\$\{documentation_?root_?url\}", re.I)
# Placeholders of a link built at run time: `${x}`, `%s`, `{0}`.
TEMPLATE_RE = re.compile(r"\$\{|%s|%d(?![0-9A-Fa-f])|\{\d*\}")
TRAILING_PUNCTUATION = ".,;:!?)]}|"
REFRESH_RE = re.compile(r"""http-equiv=["']refresh["'][^>]*content=["']\d+;\s*url=([^"']+)["']""", re.I)


def page_file(site: Path, url_path: str) -> Path | None:
    for candidate in (site / url_path / "index.html", site / url_path):
        if candidate.is_file():
            return candidate
    return None


@cache
def read_page(page: Path) -> str:
    return page.read_text(encoding="utf-8")


class PageAnchors(HTMLParser):
    """Collect the anchors of a page: every id, and the name of every <a>."""

    def __init__(self) -> None:
        super().__init__()
        self.anchors: set[str] = set()

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        for name, value in attrs:
            if value and (name == "id" or (tag == "a" and name == "name")):
                self.anchors.add(value)


@cache
def anchors_of(page: Path) -> frozenset[str]:
    parser = PageAnchors()
    parser.feed(read_page(page))
    return frozenset(parser.anchors)


def version_path(url: str) -> str | None:
    """Path of a docs.openaev.io URL under /latest/, relative to the site root, or None when it is outside it."""
    parts = urlsplit(url)
    if parts.netloc.lower() != "docs.openaev.io":
        return None
    path = unquote(parts.path)
    if path.rstrip("/") == "/latest":
        return ""
    return path.removeprefix("/latest/").strip("/") if path.startswith("/latest/") else None


def follow_redirects(site: Path, url_path: str) -> tuple[str, Path | None, str, str | None]:
    """Follow meta-refresh redirect pages.

    Return the final URL path, its page (None when missing), the fragment the redirect targets add
    and an error message when the chain cannot be followed.
    """
    fragment, seen = "", set()
    while url_path not in seen:
        seen.add(url_path)
        page = page_file(site, url_path)
        if page is None:
            return url_path, None, fragment, None
        if page.suffix != ".html":
            return url_path, page, fragment, None
        refresh = REFRESH_RE.search(read_page(page))
        if not refresh:
            return url_path, page, fragment, None
        target_url = urljoin(VERSION_ROOT + page.relative_to(site).as_posix(), refresh.group(1))
        target_path = version_path(target_url)
        if target_path is None:
            return url_path, page, fragment, f"redirect leaves {VERSION_ROOT} for {target_url}"
        target_fragment = unquote(urlsplit(target_url).fragment)
        if fragment and target_fragment:
            # The redirect page appends the incoming fragment to its target: `target#a#b` resolves nowhere.
            return url_path, page, fragment, f"redirects add two anchors, #{fragment} and #{target_fragment}"
        fragment = fragment or target_fragment
        url_path = target_path
    return url_path, None, fragment, f"redirect loop on {url_path or 'index'}"


def check_url(site: Path, url: str) -> str | None:
    parts = urlsplit(ROOT_CONSTANT_RE.sub(ROOT, url))
    if TEMPLATE_RE.search(parts.path):
        return None  # built at run time, there is nothing to resolve statically
    segments = [unquote(s) for s in parts.path.split("/") if s]
    if not segments:
        return None
    if segments[0] != "latest":
        return "link must start with /latest/"
    url_path, page, target_fragment, error = follow_redirects(site, "/".join(segments[1:]))
    if error:
        return error
    if page is None:
        return f"no page {url_path or 'index'} in the built docs site"
    link_fragment = "" if TEMPLATE_RE.search(parts.fragment) else unquote(parts.fragment)
    if link_fragment and target_fragment:
        return f"redirect already targets #{target_fragment}, a link cannot add #{link_fragment}"
    fragment = link_fragment or target_fragment
    if fragment and (page.suffix != ".html" or fragment not in anchors_of(page)):
        return f"no anchor #{fragment} on {page.relative_to(site).as_posix()}"
    return None


def strip_trailing_punctuation(url: str) -> str:
    """Drop the punctuation that ends the sentence or string around a link, not the closing `}` of `${x}` or `{0}`."""
    while url and url[-1] in TRAILING_PUNCTUATION:
        if url[-1] == "}" and url.count("{") >= url.count("}"):
            break
        url = url[:-1]
    return url


class ContentLinks(HTMLParser):
    """Collect the href of every <a> in the content of a built page, its <article>, not the theme around it."""

    def __init__(self) -> None:
        super().__init__()
        self.depth = 0
        self.hrefs: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag == "article":
            self.depth += 1
        elif tag == "a" and self.depth:
            href = dict(attrs).get("href")
            if href:
                self.hrefs.append(href)

    def handle_endtag(self, tag: str) -> None:
        if tag == "article" and self.depth:
            self.depth -= 1


def stays_on_docs_site(href: str) -> bool:
    """False for a link to another site, or a mailto: one."""
    parts = urlsplit(href)
    return parts.netloc.lower() == "docs.openaev.io" or not (parts.scheme or parts.netloc)


def check_page_link(site: Path, page: Path, href: str) -> str | None:
    if urlsplit(href).netloc:
        return check_url(site, href)
    if href.startswith("/"):
        # The site is served under a version, /latest/: a root path skips it.
        return f"link must be relative, or start with {VERSION_ROOT}"
    # Resolve against the URL the page is served at, so a `..` too many leaves /latest/.
    url = urljoin(VERSION_ROOT + page.relative_to(site).as_posix().removesuffix("index.html"), href)
    return f"link leaves {VERSION_ROOT}" if version_path(url) is None else check_url(site, url)


def source_of(site: Path, page: Path) -> str:
    """The Markdown file a built page comes from, for the error annotation, or the page itself."""
    stem = page.relative_to(site).parent
    candidates = [DOCS_ROOT / stem / "index.md", DOCS_ROOT / stem / "README.md"]
    if stem != Path("."):
        candidates.insert(0, DOCS_ROOT / f"{stem}.md")
    if page.name == "index.html":
        for candidate in candidates:
            if candidate.is_file():
                return candidate.relative_to(REPO).as_posix()
    return page.relative_to(REPO).as_posix() if page.is_relative_to(REPO) else page.as_posix()


def check_docs_pages(site: Path) -> tuple[int, list[tuple[str, int | None, str, str]]]:
    checked, errors = 0, []
    for page in sorted(site.rglob("*.html")):
        parser = ContentLinks()
        parser.feed(read_page(page))
        for href in filter(stays_on_docs_site, parser.hrefs):
            checked += 1
            error = check_page_link(site, page, href)
            if error:
                errors.append((source_of(site, page), None, href, error))
    return checked, errors


def source_files() -> list[Path]:
    listed = subprocess.run(
        ["git", "ls-files", "--", *SOURCE_DIRS],
        cwd=REPO, check=True, capture_output=True, text=True,
    ).stdout.splitlines()
    return [REPO / f for f in listed if Path(f).suffix in SOURCE_SUFFIXES]


def main() -> int:
    site = Path(sys.argv[1]) if len(sys.argv) > 1 else REPO / "docs" / "site"
    if not (site / "index.html").is_file():
        print(f"::error::{site} is not a built MkDocs site: run `mkdocs build` in docs/ first.")
        return 2

    checked, errors = 0, []
    for file in source_files():
        rel = file.relative_to(REPO).as_posix()
        for line_no, line in enumerate(file.read_text(encoding="utf-8", errors="replace").splitlines(), 1):
            for url in map(strip_trailing_punctuation, URL_RE.findall(line)):
                checked += 1
                error = check_url(site, url)
                if error:
                    errors.append((rel, line_no, url, error))

    checked_in_docs, docs_errors = check_docs_pages(site)
    errors += docs_errors

    for rel, line_no, url, error in errors:
        location = f"file={rel},line={line_no}" if line_no else f"file={rel}"
        print(f"::error {location}::{url}: {error}")
    print(f"Checked {checked} docs link(s) in the code and {checked_in_docs} in the docs pages, {len(errors)} broken.")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
